//! Runtime COMBINE boundary.
use crate::combine::{bond_strength,eligible_candidates,required_investment,ExperimentalInteraction,FormationEvaluation};
use crate::contact::ConnectionCompatibilityCache;
use crate::resources::{BaseResource,ConnectionSites,Material};
use crate::state::{Environment,Organism};
use crate::structure::{BondEndpoint,ConnectionEndpoint,Placement,StructuralUnit};
const EPSILON:f64=1e-12;const COMBINE_CONTACT_TOLERANCE:f64=1.0;
#[derive(Clone,Copy,Debug,PartialEq)]pub(crate)struct CombineAttempt{pub unit_a:usize,pub unit_b:usize,pub endpoint_a:ConnectionEndpoint,pub endpoint_b:ConnectionEndpoint,pub work_cost:f64,pub energy_invested:f64,pub interaction_direction:f64,pub interaction_magnitude:f64,pub interaction_energy:f64,pub formation_threshold:f64,pub net_energy_change:f64,pub bond_strength:f64,pub bond_energy:f64}
fn water_field_amount(environment:&Environment,organism:&Organism)->f64{organism.occupied_cells.first().and_then(|p|environment.field.index_for_position(p.x,p.y)).map(|i|environment.field.cells[i].materials.iter().flat_map(|m|m.parts.iter()).filter(|(n,_)|n=="Water").map(|(_,a)|*a).sum()).unwrap_or(0.0)}
fn placement_for_connection(existing:&crate::structure::StructuralUnit,existing_point:crate::resources::ConnectionPoint,new_point:crate::resources::ConnectionPoint)->Placement{let w=crate::contact::world_connection_point(existing_point,existing);let angle=w.normal_y.atan2(w.normal_x);let rotation=angle+std::f64::consts::PI-new_point.direction_radians;let(s,c)=rotation.sin_cos();let rx=new_point.x*c-new_point.y*s;let ry=new_point.x*s+new_point.y*c;Placement{x:w.x-rx,y:w.y-ry,rotation_radians:rotation}}
fn placement_for_continuous_new(existing:&crate::structure::StructuralUnit,existing_point:crate::resources::ConnectionPoint,new_shape:&crate::resources::Shape)->Placement{let w=crate::contact::world_connection_point(existing_point,existing);let radius=new_shape.form.bounding_radius();Placement{x:w.x+w.normal_x*radius,y:w.y+w.normal_y*radius,rotation_radians:0.0}}
fn energy_requirements(investment:f64,work:f64,interaction:f64)->Option<f64>{if !investment.is_finite()||investment<0.0||!work.is_finite()||work<0.0||!interaction.is_finite(){return None}let required=investment+work-interaction;if !required.is_finite(){return None}Some(required.max(0.0))}
fn can_afford(organism:&Organism,investment:f64,work:f64,interaction:f64,threshold:f64)->bool{let Some(required)=energy_requirements(investment,work,interaction)else{return false};crate::combine::formation_succeeds(FormationEvaluation{candidate:crate::contact::ConnectionPairCandidate{endpoint_a:ConnectionEndpoint::Corner{point_index:0},endpoint_b:ConnectionEndpoint::Corner{point_index:0},distance:0.0,facing:1.0,load_a:0.0,load_b:0.0,available_a:true,available_b:true},threshold},investment)&&organism.usable_energy+EPSILON>=threshold.max(required)}
fn settle_energy(organism:&mut Organism,investment:f64,work:f64,interaction:f64)->Option<f64>{let required=energy_requirements(investment,work,interaction)?;if organism.usable_energy+EPSILON<required{return None}let net=interaction-investment-work;if !net.is_finite(){return None}organism.usable_energy+=net;if organism.usable_energy< -EPSILON{return None}if organism.usable_energy<0.0{organism.usable_energy=0.0}organism.add_transaction_stress(work);Some(net)}
pub(crate)fn instantiate_one_unit(organism:&mut Organism,catalog:&[BaseResource])->Option<usize>{let material=organism.stored_material.peek_one_unstructured()?;let resource_name=material.parts.first().filter(|(_,a)|(*a-1.0).abs()<=EPSILON).map(|(n,_)|n.clone())?;if material.parts.len()!=1||catalog.iter().all(|b|b.name!=resource_name){return None}let material=organism.stored_material.take_one_unstructured_named(&resource_name)?;let(x,y)=organism.occupied_cells.first().map(|p|(p.x,p.y)).unwrap_or((0.0,0.0));debug_assert_eq!(material.total_amount(),1.0);Some(organism.structure.add_unit(StructuralUnit::from_material(material,Placement{x,y,rotation_radians:0.0})?))}
pub(crate)fn try_combine_stored_unit(organism:&mut Organism,environment:&Environment,cache:&mut ConnectionCompatibilityCache)->Option<CombineAttempt>{let raw=organism.stored_material.peek_one_unstructured()?;if raw.parts.len()!=1||!raw.internal_bonds.is_empty()||(raw.parts[0].1-1.0).abs()>EPSILON||environment.catalog.iter().all(|b|b.name!=raw.parts[0].0){return None}let resource_name=raw.parts[0].0.clone();let resource=environment.catalog.iter().find(|b|b.name==resource_name)?;let mut best:Option<(usize,Placement,FormationEvaluation,ExperimentalInteraction,f64)>=None;let water=water_field_amount(environment,organism);for ua in 0..organism.structure.units.len(){let Some(ConnectionSites::Corners(existing))=organism.structure.units[ua].connection_sites(&environment.catalog)else{continue};for(_pa,&ep)in existing.iter().enumerate(){let placements=match resource.shape.connection_sites(){ConnectionSites::Corners(new_sites)=>new_sites.iter().map(|np|placement_for_connection(&organism.structure.units[ua],ep,*np)).collect::<Vec<_>>(),ConnectionSites::Circumference{..}|ConnectionSites::Undetermined=>vec![placement_for_continuous_new(&organism.structure.units[ua],ep,&resource.shape)]};for placement in placements{let mut hypothetical=organism.structure.clone();let ub=hypothetical.add_unit(StructuralUnit::from_material(raw.clone(),placement)?);for candidate in crate::contact::connection_pair_candidates_cached(&hypothetical,ua,ub,&environment.catalog,cache).into_iter().filter(|c|c.distance<=COMBINE_CONTACT_TOLERANCE&&c.available_a&&c.available_b){let a=hypothetical.units[ua].properties(&environment.catalog)?;let b=hypothetical.units[ub].properties(&environment.catalog)?;let evaluation=crate::combine::evaluate_formation(candidate,a.cohesion,b.cohesion);let(interaction,work,threshold)=required_investment(a,b,evaluation,water).ok()?;let required=energy_requirements(threshold,work,interaction.signed_value)?;if best.as_ref().map(|x|required<x.4).unwrap_or(true){best=Some((ua,placement,evaluation,interaction,required));}}}}}let(ua,placement,evaluation,interaction,_)=best?;let investment=evaluation.threshold;let props_a=organism.structure.units[ua].properties(&environment.catalog)?;let props_b=resource.properties;let work=crate::combine::experimental_combine_work_cost(props_a,props_b,evaluation.candidate,water);if !can_afford(organism,investment,work,interaction.signed_value,evaluation.threshold){return None}let bs=bond_strength(props_a,props_b);if !bs.is_finite(){return None}let material=organism.stored_material.take_one_unstructured_named(&resource_name)?;let ub=match StructuralUnit::from_material(material.clone(),placement){Some(u)=>organism.structure.add_unit(u),None=>{debug_assert!(organism.store_material(material));return None}};let new_endpoint=evaluation.candidate.endpoint_b;let bond=crate::structure::Bond{endpoint_a:BondEndpoint{unit_index:ua,location:evaluation.candidate.endpoint_a},endpoint_b:BondEndpoint{unit_index:ub,location:new_endpoint},strength:bs,bond_energy:investment};let _bond_index=match crate::contact::try_add_bond(&mut organism.structure,bond,&environment.catalog){Ok(i)=>i,Err(_)=>{organism.structure.units.pop();debug_assert!(organism.store_material(material));return None}};let net=match settle_energy(organism,investment,work,interaction.signed_value){Some(n)=>n,None=>{organism.structure.bonds.pop();organism.structure.units.pop();debug_assert!(organism.store_material(material));return None}};Some(CombineAttempt{unit_a:ua,unit_b:ub,endpoint_a:evaluation.candidate.endpoint_a,endpoint_b:new_endpoint,work_cost:work,energy_invested:investment,interaction_direction:interaction.direction,interaction_magnitude:interaction.magnitude,interaction_energy:interaction.signed_value,formation_threshold:evaluation.threshold,net_energy_change:net,bond_strength:bs,bond_energy:investment})}
pub(crate)fn try_combine(organism:&mut Organism,environment:&Environment,cache:&mut ConnectionCompatibilityCache)->Option<CombineAttempt>{if !organism.structure.units.is_empty()&&!organism.stored_material.is_empty(){if let Some(a)=try_combine_stored_unit(organism,environment,cache){return Some(a)}}if organism.structure.units.len()<2{return None}let catalog=&environment.catalog;let mut best:Option<(usize,usize,FormationEvaluation)>=None;for ua in 0..organism.structure.units.len(){for ub in ua+1..organism.structure.units.len(){for e in eligible_candidates(&organism.structure,ua,ub,catalog,cache).into_iter().filter(|c|c.distance<=COMBINE_CONTACT_TOLERANCE).filter_map(|c|{let a=organism.structure.units[ua].properties(catalog)?;let b=organism.structure.units[ub].properties(catalog)?;Some(crate::combine::evaluate_formation(c,a.cohesion,b.cohesion))}){if best.as_ref().map(|(_,_,x)|e.candidate.distance<x.candidate.distance).unwrap_or(true){best=Some((ua,ub,e));}}}}let(ua,ub,e)=best?;let a=organism.structure.units[ua].properties(catalog)?;let b=organism.structure.units[ub].properties(catalog)?;let(interaction,work,threshold)=required_investment(a,b,e,water_field_amount(environment,organism)).ok()?;let investment=threshold;if !can_afford(organism,investment,work,interaction.signed_value,threshold){return None}let bs=bond_strength(a,b);if !bs.is_finite(){return None}let bond=crate::structure::Bond{endpoint_a:BondEndpoint{unit_index:ua,location:e.candidate.endpoint_a},endpoint_b:BondEndpoint{unit_index:ub,location:e.candidate.endpoint_b},strength:bs,bond_energy:investment};let _bond_index=crate::contact::try_add_bond(&mut organism.structure,bond,catalog).ok()?;let net=match settle_energy(organism,investment,work,interaction.signed_value){Some(n)=>n,None=>{organism.structure.bonds.pop();return None}};Some(CombineAttempt{unit_a:ua,unit_b:ub,endpoint_a:e.candidate.endpoint_a,endpoint_b:e.candidate.endpoint_b,work_cost:work,energy_invested:investment,interaction_direction:interaction.direction,interaction_magnitude:interaction.magnitude,interaction_energy:interaction.signed_value,formation_threshold:threshold,net_energy_change:net,bond_strength:bs,bond_energy:investment})}
#[allow(dead_code)]fn _raw_material_type_check(raw:&Material,catalog:&[BaseResource])->bool{!raw.has_internal_structure()&&raw.parts.iter().all(|(n,a)|*a>=0.0&&catalog.iter().any(|r|r.name==*n))}
